            Assert.Equal("La Marea se retira de Los Llanos de Ceniza", Lore.MareaAlert(5, "Los Llanos de Ceniza", false).Title);
            Assert.Equal("La Marea se retira de Los Llanos de Ceniza. Vuelve a haber quien conteste por radio.", Lore.MareaAlert(5, "Los Llanos de Ceniza", false).Text);
            Assert.Equal("Los muertos han tomado Tarbes: nadie contesta hasta que se retiren.", Lore.FloodedContactReason(2, "Tarbes"));
            Assert.Equal("En manos de los muertos: Tarbes", Lore.FloodedListLabel(2, new[] { "Tarbes" }));
            Assert.Equal("En manos de los muertos: Tarbes, Koper y Rudnik", Lore.FloodedListLabel(2, new[] { "Tarbes", "Koper", "Rudnik" }));
            Assert.Equal("En manos de los muertos: de aquí no llega nada, y sus misiones traen un grupo más. Saldrá si baja la infestación: quemad Nidos.", Lore.FloodedZoneNote(2));
            Assert.Equal("La Marea cubre Tarbes: nadie contesta hasta que se retire.", Lore.FloodedContactReason(5, "Tarbes"));
            Assert.Equal("Bajo la Marea: Tarbes", Lore.FloodedListLabel(5, new[] { "Tarbes" }));
            Assert.Equal("Bajo la Marea: Tarbes, Koper y Rudnik", Lore.FloodedListLabel(5, new[] { "Tarbes", "Koper", "Rudnik" }));
            Assert.Equal("Bajo la Marea: de aquí no llega nada, y sus misiones traen un grupo más de muertos. Saldrá si la Marea retrocede: quemad Nidos.", Lore.FloodedZoneNote(5));
            Assert.Equal("No hay carretera desde vuestras zonas: contactad antes con otra zona.", Lore.NoRoadReason(new string[] {  }));
            Assert.Equal("No hay carretera desde vuestras zonas: contactad antes con Bielsa.", Lore.NoRoadReason(new string[] { "Bielsa" }));
            Assert.Equal("No hay carretera desde vuestras zonas: contactad antes con Bielsa o La Vega.", Lore.NoRoadReason(new string[] { "Bielsa", "La Vega" }));
        }
    }
